$ErrorActionPreference='Continue'
$repo='C:\Users\PC\Desktop\CLIENTS\HONEST-ESTATE-WEBSITE';$source='C:\Users\PC\Desktop\CLIENTS\HONEST ESTATE DEVELOPERS RESOURCES';$outDir=Join-Path $repo 'public\videos\2026\hed-highlights';$brandDir=Join-Path $repo 'public\video-branding';New-Item -ItemType Directory -Force -Path $outDir|Out-Null
$items=@(
@{Old='WhatsApp Video 2026-10-13 at 10.09.19.mp4';New='HED Property Experience 01 - Aerial View.mp4';Web='hed-property-experience-01-aerial-view.mp4'},
@{Old='WhatsApp Video 2026-10-13 at 10.09.54.mp4';New='HED Property Experience 02 - Site Tour.mp4';Web='hed-property-experience-02-site-tour.mp4'},
@{Old='WhatsApp Video 2026-10-13 at 10.12.22 (1).mp4';New='HED Property Experience 03 - Property Briefing.mp4';Web='hed-property-experience-03-property-briefing.mp4'},
@{Old='WhatsApp Video 2026-10-13 at 10.12.22 (2).mp4';New='HED Property Experience 04 - Estate Presentation.mp4';Web='hed-property-experience-04-estate-presentation.mp4'},
@{Old='WhatsApp Video 2026-10-13 at 10.12.22 (3).mp4';New='HED Property Experience 05 - Field Visit.mp4';Web='hed-property-experience-05-field-visit.mp4'})
function Add-EndCard([string]$sourcePath,[string]$destPath){$meta=& ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 -- "$sourcePath";$parts=$meta.Trim().Split(',');$w=[int]$parts[0];$h=[int]$parts[1];$card=if($w -gt $h){Join-Path $brandDir 'hed-end-card-landscape.png'}else{Join-Path $brandDir 'hed-end-card-portrait.png'};$audio=(& ffprobe -v error -select_streams a:0 -show_entries stream=codec_name -of csv=p=0 -- "$sourcePath").Trim();$tmp=$destPath+'.tmp.mp4';if(Test-Path $tmp){Remove-Item $tmp -Force};if($audio){& ffmpeg -loglevel error -y -i "$sourcePath" -loop 1 -t 5 -i "$card" -f lavfi -t 5 -i 'anullsrc=r=48000:cl=stereo' -filter_complex "[0:v]fps=30,format=yuv420p,setpts=PTS-STARTPTS[v0];[1:v]scale=$w`:$h,fps=30,format=yuv420p,setpts=PTS-STARTPTS[v1];[0:a]aresample=48000,aformat=sample_rates=48000:channel_layouts=stereo,asetpts=PTS-STARTPTS[a0];[2:a]asetpts=PTS-STARTPTS[a1];[v0][a0][v1][a1]concat=n=2:v=1:a=1[v][a]" -map '[v]' -map '[a]' -c:v libx264 -preset veryfast -crf 24 -c:a aac -b:a 128k -movflags +faststart "$tmp"}else{$dur=(& ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 -- "$sourcePath").Trim();& ffmpeg -loglevel error -y -i "$sourcePath" -loop 1 -t 5 -i "$card" -f lavfi -t $dur -i 'anullsrc=r=48000:cl=stereo' -f lavfi -t 5 -i 'anullsrc=r=48000:cl=stereo' -filter_complex "[0:v]fps=30,format=yuv420p,setpts=PTS-STARTPTS[v0];[1:v]scale=$w`:$h,fps=30,format=yuv420p,setpts=PTS-STARTPTS[v1];[2:a]asetpts=PTS-STARTPTS[a0];[3:a]asetpts=PTS-STARTPTS[a1];[v0][a0][v1][a1]concat=n=2:v=1:a=1[v][a]" -map '[v]' -map '[a]' -c:v libx264 -preset veryfast -crf 24 -c:a aac -b:a 128k -movflags +faststart "$tmp"};if($LASTEXITCODE -ne 0){throw "ffmpeg failed for $sourcePath"};Move-Item -Force $tmp $destPath}
foreach($item in $items){$oldPath=Join-Path $source $item.Old;$newPath=Join-Path $source $item.New;if((Test-Path $oldPath)-and-not(Test-Path $newPath)){Move-Item $oldPath $newPath;Write-Output "Renamed: $($item.Old) -> $($item.New)"};if(-not(Test-Path $newPath)){throw "Missing source video: $newPath"};$webPath=Join-Path $outDir $item.Web;Write-Output "Branding $($item.New)...";Add-EndCard $newPath $webPath;$stem=[IO.Path]::GetFileNameWithoutExtension($item.Web);$poster=Join-Path $outDir ($stem+'-poster.jpg');& ffmpeg -loglevel error -y -ss 3 -i "$webPath" -frames:v 1 -q:v 2 "$poster";if($LASTEXITCODE -ne 0){throw "poster failed for $webPath"}}
$mpDir=Join-Path $repo 'public\videos\2026\mpambire';foreach($name in @('mpambire-drone-overview.mp4','mpambire-site-visit-1.mp4','mpambire-site-visit-3.mp4')){$path=Join-Path $mpDir $name;$temp=Join-Path $mpDir ('branded-'+$name);Write-Output "Adding HED contact ending to $name...";Add-EndCard $path $temp;Move-Item -Force $temp $path}
Write-Output 'All HED videos prepared with branded contact endings.'
